// Removes the "Generated by/with Claude Code" footer from a pull request body.
// Cloud sessions get it from the platform (AGENTS.md hard rule 6 forbids it).
// The workflow .github/workflows/strip-attribution.yml calls this function.

const footer = /^[ \t]*(?:🤖[ \t]*)?_?Generated (?:by|with) \[Claude Code\]\([^)\s]*\)_?[ \t]*$/gim;

export function stripAttribution(body) {
    if (!body) {
        return '';
    }

    if (!footer.test(body)) {
        return body;
    }

    footer.lastIndex = 0;

    return body
        .replace(footer, '')
        .trimEnd()
        .replace(/\n+---$/, '')
        .trimEnd();
}
